import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Inspect{public static void main(String[]a)throws Exception{ClassNode packet=new ClassNode();try(ZipFile z=new ZipFile(a[0])){new ClassReader(z.getInputStream(z.getEntry("mod/cdv/tnpc/network/AnimationPacket.class"))).accept(packet,0);}if(packet.methods.stream().noneMatch(m->m.name.equals("<init>")&&m.desc.equals("(BI)V")))throw new AssertionError("native byte/int action constructor");ClassNode flash=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(a[1]))).accept(flash,0);Set<String> methods=new HashSet<>();for(var m:flash.methods)methods.add(m.name+m.desc);String render="render(Lcom/mojang/blaze3d/vertex/PoseStack;Lcom/mojang/blaze3d/vertex/VertexConsumer;Lnet/minecraft/world/item/ItemDisplayContext;II)V";if(!methods.contains(render)||!methods.contains("doRender(IILcom/tacz/guns/client/resource/pojo/display/gun/MuzzleFlash;J)V"))throw new AssertionError("native muzzle ABI");Set<String> fields=new HashSet<>();for(var f:flash.fields)fields.add(f.name);if(!fields.containsAll(Set.of("bedrockGunModel","muzzleFlashNormal","muzzleFlashPose","muzzleFlashRandomRotate")))throw new AssertionError("native muzzle fields");ClassNode mixin=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(a[2]))).accept(mixin,0);int count=0;for(var m:mixin.methods){new Analyzer<BasicValue>(new BasicVerifier()).analyze(mixin.name,m);if(m.visibleAnnotations==null)continue;for(var an:m.visibleAnnotations)if(an.desc.endsWith("/Inject;"))for(int i=0;i<an.values.size();i+=2)if(an.values.get(i).equals("method")){if(!((List<?>)an.values.get(i+1)).contains(render))throw new AssertionError("muzzle mixin target");count++;}}if(count!=1)throw new AssertionError("one native muzzle injection");System.out.println("NATIVE_BYTE_PACKET_MUZZLE_FIELDS_METHODS_AND_MIXIN_ABI_VERIFIED=PASS");}}
